class Solution {
public:
    std::vector<int> minCostAlternatingPath(int n, std::vector<std::vector<int>>& redEdges, std::vector<std::vector<int>>& blueEdges) {
        std::vector<std::vector<int>> redAdj(n), blueAdj(n);
        for (auto& e : redEdges) redAdj[e[0]].push_back(e[1]);
        for (auto& e : blueEdges) blueAdj[e[0]].push_back(e[1]);
        std::vector<std::vector<int>> dist(n, std::vector<int>(2, -1));
        dist[0][0] = 0; dist[0][1] = 0;
        std::queue<std::pair<int, int>> q;
        q.push({0, 0}); q.push({0, 1});
        while (!q.empty()) {
            auto [u, color] = q.front();
            q.pop();
            int d = dist[u][color];
            if (color == 0) {
                for (int v : blueAdj[u]) {
                    if (dist[v][1] == -1) {
                        dist[v][1] = d + 1;
                        q.push({v, 1});
                    }
                }
            } else {
                for (int v : redAdj[u]) {
                    if (dist[v][0] == -1) {
                        dist[v][0] = d + 1;
                        q.push({v, 0});
                    }
                }
            }
        }
        std::vector<int> res(n);
        for (int i = 0; i < n; ++i) {
            int d0 = dist[i][0], d1 = dist[i][1];
            if (d0 == -1 && d1 == -1) res[i] = -1;
            else if (d0 == -1) res[i] = d1;
            else if (d1 == -1) res[i] = d0;
            else res[i] = std::min(d0, d1);
        }
        return res;
    }
};

import java.util.*;

class Solution {
    public int[] minCostAlternatingPath(int n, int[][] redEdges, int[][] blueEdges) {
        List<List<Integer>> redAdj = new ArrayList<>();
        List<List<Integer>> blueAdj = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            redAdj.add(new ArrayList<>());
            blueAdj.add(new ArrayList<>());
        }
        for (int[] e : redEdges) redAdj.get(e[0]).add(e[1]);
        for (int[] e : blueEdges) blueAdj.get(e[0]).add(e[1]);
        int[][] dist = new int[n][2];
        for (int[] row : dist) Arrays.fill(row, -1);
        dist[0][0] = 0; dist[0][1] = 0;
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{0, 0});
        q.offer(new int[]{0, 1});
        while (!q.isEmpty()) {
            int[] top = q.poll();
            int u = top[0], color = top[1];
            int d = dist[u][color];
            if (color == 0) {
                for (int v : blueAdj.get(u)) {
                    if (dist[v][1] == -1) {
                        dist[v][1] = d + 1;
                        q.offer(new int[]{v, 1});
                    }
                }
            } else {
                for (int v : redAdj.get(u)) {
                    if (dist[v][0] == -1) {
                        dist[v][0] = d + 1;
                        q.offer(new int[]{v, 0});
                    }
                }
            }
        }
        int[] res = new int[n];
        for (int i = 0; i < n; i++) {
            int d0 = dist[i][0], d1 = dist[i][1];
            if (d0 == -1 && d1 == -1) res[i] = -1;
            else if (d0 == -1) res[i] = d1;
            else if (d1 == -1) res[i] = d0;
            else res[i] = Math.min(d0, d1);
        }
        return res;
    }
}

function minCostAlternatingPath(n, redEdges, blueEdges) {
    const redAdj = Array.from({ length: n }, () => []);
    const blueAdj = Array.from({ length: n }, () => []);
    for (const [u, v] of redEdges) redAdj[u].push(v);
    for (const [u, v] of blueEdges) blueAdj[u].push(v);
    const dist = Array.from({ length: n }, () => [-1, -1]);
    dist[0][0] = 0; dist[0][1] = 0;
    const q = [[0, 0], [0, 1]];
    let head = 0;
    while (head < q.length) {
        const [u, color] = q[head++];
        const d = dist[u][color];
        if (color === 0) {
            for (const v of blueAdj[u]) {
                if (dist[v][1] === -1) {
                    dist[v][1] = d + 1;
                    q.push([v, 1]);
                }
            }
        } else {
            for (const v of redAdj[u]) {
                if (dist[v][0] === -1) {
                    dist[v][0] = d + 1;
                    q.push([v, 0]);
                }
            }
        }
    }
    const res = [];
    for (let i = 0; i < n; i++) {
        const [d0, d1] = dist[i];
        if (d0 === -1 && d1 === -1) res.push(-1);
        else if (d0 === -1) res.push(d1);
        else if (d1 === -1) res.push(d0);
        else res.push(Math.min(d0, d1));
    }
    return res;
}
